def test_material_ends_at_a_gasket_or_connector_behavior():
    # the cards after *GASKET BEHAVIOR / *CONNECTOR BEHAVIOR are that behaviour's, not the
    # material's before it: every material walker ends a material there (_material_groups)
    deck = ("*MATERIAL, NAME=STEEL\n*ELASTIC\n210000., 0.3\n*DENSITY\n7.8e-9\n"
            "*GASKET BEHAVIOR, NAME=G\n*DENSITY\n1e-12\n"
            "*CONNECTOR BEHAVIOR, NAME=C\n*ELASTIC, TYPE=ORTHOTROPIC\n1e9, 1e9, 1e9, 1e9, 1e9, 1e9, 1e9, 1e9, 1e9\n"
            "*SOLID SECTION, ELSET=EALL, MATERIAL=STEEL\n")
    blocks = A.blocks_from_lines(deck.splitlines())
    conv = A.Converter(A.Report(), Opt())
    conv._approx = False
    c = math.sqrt(210000. * 0.7 / (1.3 * 0.4 * 7.8e-9))
    assert conv._wave_speeds(blocks) == {"STEEL": c}
    assert conv._all_wave_speeds(blocks) == {"STEEL": c}
    assert [g[0].uparam("NAME") for g in conv._material_groups(blocks)] == ["STEEL"]


def test_ref_node_set_of_several_nodes_warned_on_kinematic_coupling():
    # Abaqus requires a *KINEMATIC COUPLING / *RIGID BODY REF NODE set to hold one node; the
    # legacy *KINEMATIC COUPLING took the first of several without a word
    deck = HEX + ("*NODE\n9, 0.5, 0.5, 2.\n10, 0.5, 0.5, 3.\n*NSET, NSET=RP\n9, 10\n"
                  "*NSET, NSET=TOP\n5, 6, 7, 8\n*MATERIAL, NAME=M\n*ELASTIC\n1000., 0.3\n"
                  "*SOLID SECTION, ELSET=EALL, MATERIAL=M\n"
                  "*KINEMATIC COUPLING, REF NODE=RP\nTOP, 1, 3\n*BOUNDARY\n1, 1, 3\n2, 1, 3\n"
                  "3, 1, 3\n4, 1, 3\n*STEP\n*STATIC\n*CLOAD\n9, 3, 1.\n*END STEP\n")
    body, conv, rep = convert_str(deck)
    assert "REF NODE=9," in body
    assert "*KINEMATIC COUPLING REF NODE=RP names a set of 2 nodes, where Abaqus requires one; " \
        "the first (9) is used" in rep.text()
    body, conv, rep = convert_str(deck.replace("*NSET, NSET=RP\n9, 10", "*NSET, NSET=RP\n9"))
    assert "*KINEMATIC COUPLING REF NODE=RP resolved to node 9" in rep.text()
    rb = deck.replace("*KINEMATIC COUPLING, REF NODE=RP\nTOP, 1, 3", "*RIGID BODY, REF NODE=RP, TIE NSET=TOP")
    body, conv, rep = convert_str(rb)
    assert "*RIGID BODY REF NODE=RP names a set of 2 nodes, where Abaqus requires one; the first (9)" \
        in rep.text() and "REF NODE=9" in body


def test_rotary_inertia_in_a_turned_orientation():
    # the *ORIENTATION's additional rotation turns the local inertia axes (the orientation
    # defines them, Keywords *ROTARY INERTIA): the same as the orientation written turned
    def inertia(ori):
        deck = RIGID_PLATE + ori + ("*ELEMENT, TYPE=MASS, ELSET=PM\n10, 9\n*MASS, ELSET=PM\n6.\n"
                                    "*ELEMENT, TYPE=ROTARYI, ELSET=PI\n11, 9\n"
                                    "*ROTARY INERTIA, ELSET=PI, ORIENTATION=O\n1.5, 2., 1., 0.1, 0., 0.\n"
                                    "*STEP\n*FREQUENCY\n3\n*END STEP\n")
        body, _, rep = convert_str(deck)
        assert "not converted" not in rep.text(), rep.text()
        g = reparse(body)
        masses = {}
        for m in re.finditer(r"\*MASS, ELSET=(\S+)\n(\S+)\n", body):
            for e in g.elset(m.group(1)):
                masses[g.elements[e][1][0]] = masses.get(g.elements[e][1][0], 0.0) + float(m.group(2))
        c = g.nodes[9]
        return [[sum(m * ((A.vdot(A.vsub(g.nodes[n], c), A.vsub(g.nodes[n], c)) if i == j else 0.0)
                          - (g.nodes[n][i] - c[i]) * (g.nodes[n][j] - c[j])) for n, m in masses.items())
                 for j in range(3)] for i in range(3)]
    co, si = math.cos(math.radians(30.)), math.sin(math.radians(30.))
    turned = inertia("*ORIENTATION, NAME=O\n1., 0., 0., 0., 1., 0.\n3, 30.\n")
    plain = inertia(f"*ORIENTATION, NAME=O\n{co!r}, {si!r}, 0., {-si!r}, {co!r}, 0.\n")
    assert max(abs(turned[i][j] - plain[i][j]) for i in range(3) for j in range(3)) < 1e-9
    assert abs(turned[0][1]) > 0.1                                   # (turned off the global axes)
    # about axis 1: the same as the axes 2, 3 written turned
    turned = inertia("*ORIENTATION, NAME=O\n1., 0., 0., 0., 1., 0.\n1, 30.\n")
    plain = inertia(f"*ORIENTATION, NAME=O\n1., 0., 0., 0., {co!r}, {si!r}\n")
    assert max(abs(turned[i][j] - plain[i][j]) for i in range(3) for j in range(3)) < 1e-9


def test_tie_tolerance_rules_shared():
    # one rule for the membrane ties and the ties to rigid masters (they differ only in which
    # facets give the typical size)
    assert A.tie_fraction("", False, False) == 0.10
    assert A.tie_fraction("NODETOSURFACE", False, False) == 0.05
    assert A.tie_fraction("", True, False) == 0.05                  # a node-based slave
    assert A.tie_fraction("", False, True) == 0.05                  # Abaqus/Explicit's default
    assert A.tie_fraction("SURFACETOSURFACE", False, True) == 0.10
    edges = [0.1, 0.2, 0.3000000000000001]
    assert A.pair_tie_tolerance(edges) == 0.025 * (sum(edges) / 3) and A.pair_tie_tolerance([]) == 0.0


def test_boundary_line_with_a_non_numeric_last_dof():
    # one reading for every *BOUNDARY parser: a last DOF that is not an integer names no DOF
    # (ccx 2.23 stops on the line, as Abaqus reads an integer there); passed through, warned
    assert A.bc_dof_range(["1", "3"]) == (3, 3) and A.bc_dof_range(["1", "3", "", "0.5"]) == (3, 3)
    assert A.bc_dof_range(["1", "3", "1"]) == (1, 3) and A.bc_dof_range(["1", "ENCASTRE"]) is None
    assert A.bc_dof_range(["1", "3", "X", "0.01"]) is None and A.bc_dof_range(["1", "1", "3."]) is None
    deck = HEX + ("*NSET, NSET=TOP\n5, 6, 7, 8\n*MATERIAL, NAME=M\n*ELASTIC\n1000., 0.3\n"
                  "*SOLID SECTION, ELSET=EALL, MATERIAL=M\n*BOUNDARY\n1, 1, 3\n2, 1, 3\n3, 1, 3\n"
                  "4, 1, 3\n*STEP\n*STATIC\n*BOUNDARY\nTOP, 3, X, 0.01\n*END STEP\n")
    body, conv, rep = convert_str(deck)
    assert "\nTOP, 3, X, 0.01\n" in body
    assert "*BOUNDARY line 'TOP, 3, X, 0.01': its last DOF is not a number" in rep.text()
    card = [b for b in A.blocks_from_lines(deck.splitlines()) if b.keyword == "BOUNDARY"][-1]
    assert conv._bc_records(card) == [([5, 6, 7, 8], [], 0.01)]
    assert conv._rate_lines(card)[0][1] == []


def test_membrane_mass_copy_and_the_ccx_thermal_steps():
    # a membrane's section DENSITY becomes a material copy unless ccx runs a step in which the
    # copy's heat capacity acts (CCX_THERMAL_PROCS); Abaqus' thermal-electrical step is not one
    # there (commented out: ccx has no such procedure)
    deck = ("*Node\n21, 0., 3., 0.\n22, 1., 3., 0.\n23, 1., 4., 0.\n24, 0., 4., 0.\n"
            "*Element, type=M3D4, elset=SKIN\n9, 21, 22, 23, 24\n*Nset, nset=LEFT\n21, 24\n"
            "*Material, name=M\n*Elastic\n100000., 0.3\n*Density\n0.\n*Conductivity\n1.\n"
            "*Specific Heat\n1.\n*Electrical Conductivity\n1.\n"
            "*Membrane Section, elset=SKIN, material=M, density=2.\n0.01\n"
            "*Step\n*Dynamic\n0.1, 1.\n*Boundary\nLEFT, 1, 3\n*End Step\n"
            "*Step\n*{proc}\n0.1, 1.\n*End Step\n")
    body, _, _ = convert_str(deck.format(proc="Coupled Thermal-Electrical"))
    assert "*MATERIAL, NAME=M_MEMBRANE_MASS" in body
    body, _, rep = convert_str(deck.format(proc="Heat Transfer"))
    assert "M_MEMBRANE_MASS" not in body



